import AppKit
import Foundation
import Testing
@testable import CmdV

@Test func pasteboardPayloadOnlyExposesImageAndGeneratedMarkers() throws {
    let payload = PasteboardPayload(pngData: minimalPNGData, fileURL: URL(fileURLWithPath: "/tmp/cmd-v Test.png"))
    let types = Set(payload.imageItem.types)

    #expect(types.contains(.png))
    #expect(types.contains(.commandVGenerated))
    #expect(types.contains(.autoGenerated))
    #expect(!types.contains(.html))
    #expect(!types.contains(.URL))
}

private let minimalPNGData = Data([
    0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A,
    0x00, 0x00, 0x00, 0x0D, 0x49, 0x48, 0x44, 0x52,
